For $\sigma > d/p$,
\begin{align*}
    M_{S,T} \left( \B_{p,q}^\sigma(\X, L) \right)
    & \asymp M_{S,T} \left( \C^{\sigma - d/p}(\X, L) \right) \\
    & \asymp T^{1/p - \sigma/d},
\end{align*}
and, for $\sigma \in (d/p, d/p + 1]$,
\begin{align*}
    M_{C,T} \left( \B_{p,q}^\sigma(\X, L) \right)
    & \asymp M_{C,T} \left( \C^{\sigma - d/p}(\X, L) \right) \\
    & \asymp T^{1 + 1/p - \sigma/d}.
\end{align*}

